import type { EmirateName, UaeCommunityForecast, UaeCommunitySpec } from './types'

type CommSeed = [
  code: string,
  name: string,
  emirate: EmirateName,
  area: string,
  masterDeveloper: string,
  segment: UaeCommunitySpec['segment'],
  ppsf: number,
  yoyPct: number,
  yieldPct: number,
  serviceCharge: number,
  transactionsQ: number,
  offPlanShare: number,
  lat: number,
  lng: number,
  image: string,
  metro: string,
  landmarks: string[],
  schools: string[],
  hospitals: string[],
  beachOrParkMins: string,
  amenities: string[],
  ongoingProjects: string[],
]

const slugify = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')

function buildCommunity(s: CommSeed, idx: number): UaeCommunitySpec {
  const [
    code, name, emirate, area, masterDeveloper, segment, ppsf, yoyPct, yieldPct, serviceCharge,
    transactionsQ, offPlanShare, lat, lng, image, metro, landmarks, schools, hospitals,
    beachOrParkMins, amenities, ongoingProjects,
  ] = s
  const slug = slugify(name)
  const suffix = emirate === 'Dubai' ? 'DXB' : 'AUH'
  const ticker = `${code.slice(0, 4).toUpperCase()}.${suffix}`
  const ppsfLY = Math.round(ppsf / (1 + yoyPct / 100))
  const stepStart = Math.round(ppsf * 0.76)
  const trend = Array.from({ length: 9 }, (_, i) => Math.round(stepStart + ((ppsf - stepStart) * i) / 8))
  // Realistic annual rents derived from ppsf & yield
  const rentStudio = Math.round((ppsf * 450 * (yieldPct / 100)) / 1000) * 1000
  const rent1 = Math.round((ppsf * 780 * (yieldPct / 100)) / 1000) * 1000
  const rent2 = Math.round((ppsf * 1250 * (yieldPct / 100)) / 1000) * 1000
  const rent3 = Math.round((ppsf * 1950 * (yieldPct / 100)) / 1000) * 1000
  const avgRentAnnual = rent2
  const reraPrefix = emirate === 'Dubai' ? 'DLD-AREA' : 'ADM-DIST'
  const vision = emirate === 'Dubai' ? 'Dubai 2040 Urban Master Plan' : 'Abu Dhabi Vision 2030 & Plan Capital 2040'
  const growthFactor = segment === 'Prime' ? 1.072 : segment === 'Upper-mid' ? 1.064 : segment === 'Mid' ? 1.058 : 1.052
  const forecast15Y: UaeCommunityForecast[] = [
    { year: 2026, projectedPpsf: ppsf, catalyst: `Active ${offPlanShare >= 50 ? 'off-plan launch wave' : 'prime secondary absorption'} led by ${masterDeveloper}` },
    { year: 2029, projectedPpsf: Math.round(ppsf * Math.pow(growthFactor, 3) / 10) * 10, catalyst: `${metro.split('(')[0].trim()} & community retail maturation` },
    { year: 2033, projectedPpsf: Math.round(ppsf * Math.pow(growthFactor, 7) / 10) * 10, catalyst: `${vision} infrastructure & population expansion` },
    { year: 2037, projectedPpsf: Math.round(ppsf * Math.pow(growthFactor, 11) / 10) * 10, catalyst: `Mature land scarcity & institutional leasing demand across ${area}` },
    { year: 2041, projectedPpsf: Math.round(ppsf * Math.pow(growthFactor, 15) / 10) * 10, catalyst: `Long-term UAE global wealth hub appreciation & generational equity` },
  ]
  const future15YearOutlook = `${name} (${emirate}) is positioned under ${vision} with ${yoyPct >= 0 ? `+${yoyPct}%` : `${yoyPct}%`} YoY PSF momentum and ~${yieldPct}% gross rental yield. Over 2026–2041, infrastructure upgrades around ${landmarks[0] || area} and ongoing flagship launches by ${masterDeveloper} support sustained capital growth and strong end-user liquidity.`
  const closingKeywords = [
    `${segment} ${emirate} Corridor`,
    `AED ${ppsf.toLocaleString('en-US')}/sq ft`,
    `${yieldPct}% Gross Rental Yield`,
    `${yoyPct >= 0 ? `+${yoyPct}%` : `${yoyPct}%`} YoY Growth`,
    emirate === 'Dubai' ? 'Dubai 2040 Masterplan' : 'Abu Dhabi 2% ADM Fee Advantage',
    offPlanShare >= 55 ? 'High Off-Plan Upside' : 'Proven Secondary Liquidity',
  ]
  const fieldVisitPitchScript = [
    `${name} currently trades around AED ${ppsf.toLocaleString('en-US')}/sq ft (${yoyPct >= 0 ? `+${yoyPct}%` : `${yoyPct}%`} YoY) while generating approximately ${yieldPct}% gross rental yield.`,
    `Residents enjoy ${beachOrParkMins}, direct access to ${landmarks.slice(0, 2).join(' and ')}, and proximity to ${schools[0]}.`,
    `${emirate === 'Abu Dhabi' ? 'With Abu Dhabi’s 2% ADM transfer fee (half of Dubai’s 4%) and growing sovereign-backed demand,' : 'With zero property tax, USD-pegged AED stability, and 10-year Golden Visa eligibility above AED 2M,'} ${name} offers a resilient 15-year wealth trajectory.`,
  ]

  return {
    code,
    slug,
    ticker,
    name,
    emirate,
    area,
    masterDeveloper,
    reraCommunityId: `${reraPrefix}-${String(idx + 1).padStart(3, '0')}`,
    segment,
    image,
    ppsf,
    ppsfLY,
    yoyPct,
    rentStudio,
    rent1,
    rent2,
    rent3,
    avgRentAnnual,
    yieldPct,
    serviceCharge,
    transactionsQ,
    offPlanShare,
    lat,
    lng,
    trend,
    description: `${name} is a ${segment.toLowerCase()} ${emirate} destination in ${area}, master-planned by ${masterDeveloper}. Spanning ${landmarks.slice(0, 3).join(', ')}, it averages AED ${ppsf.toLocaleString('en-US')}/sq ft with ~${yieldPct}% gross yield and strong demand across both residential investors and end-users.`,
    nearby: { metro, landmarks, schools, hospitals, beachOrParkMins },
    amenities,
    ongoingProjects,
    future15YearOutlook,
    forecast15Y,
    closingKeywords,
    fieldVisitPitchScript,
  }
}

