export const UAE_COMMUNITIES: readonly UaeCommunitySpec[] = [
  ...DUBAI_SEEDS.map((s, i) => buildCommunity(s, i)),
  ...ABUDHABI_SEEDS.map((s, i) => buildCommunity(s, DUBAI_SEEDS.length + i)),
]

export const UAE_COMMUNITY_BY_CODE = new Map<string, UaeCommunitySpec>(UAE_COMMUNITIES.map(c => [c.code, c]))
export const UAE_COMMUNITY_BY_SLUG = new Map<string, UaeCommunitySpec>(UAE_COMMUNITIES.map(c => [c.slug, c]))
export const UAE_COMMUNITY_BY_NAME = new Map<string, UaeCommunitySpec>(UAE_COMMUNITIES.map(c => [c.name.toLowerCase(), c]))

export function findUaeCommunity(query?: string | null): UaeCommunitySpec | undefined {
  if (!query) return undefined
  const q = query.trim().toLowerCase()
  if (!q) return undefined
  return (
    UAE_COMMUNITY_BY_NAME.get(q) ??
    UAE_COMMUNITY_BY_SLUG.get(q) ??
    UAE_COMMUNITY_BY_CODE.get(query.trim().toUpperCase()) ??
    UAE_COMMUNITIES.find(c => q.includes(c.name.toLowerCase()) || c.name.toLowerCase().includes(q) || q.includes(c.slug.replace(/-/g, ' ')))
  )
}
